using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Gunt.ControlCenter.Models;
namespace Gunt.ControlCenter.Services {
 public sealed partial class DesktopService {
  public SessionStore Sessions(){var store=Local("development-sessions",()=>new SessionStore{Presets=new List<DevelopmentSession>{Preset("ai-coding","AI Coding","ide","ai"),Preset("opencode","OpenCode Session","ide","opencode"),Preset("web","Web Development","ide","project-terminal"),Preset("review","Review","ide","repository")}});if(store==null||store.SchemaVersion!=1||store.Presets==null)throw new InvalidDataException("개발 세션 형식을 확인하세요.");return store;}
  static DevelopmentSession Preset(string id,string name,params string[] actions){return new DevelopmentSession{Id=id,Name=name,Builtin=true,Actions=actions.Select(x=>new SessionAction{Kind=x}).ToList()};}
  static readonly string[] sessionKinds={"ai","project-terminal","ide","codex","opencode","wsl","cmd","powershell","terminal","folder","repository","command","tool"};
  public void ValidateSession(DevelopmentSession p){if(p==null||!System.Text.RegularExpressions.Regex.IsMatch(p.Id??"",@"^[a-zA-Z0-9_-]{1,80}$")||String.IsNullOrWhiteSpace(p.Name)||p.Name.Length>80||p.Actions==null||p.Actions.Count>20)throw new ArgumentException("세션 이름·ID·동작 개수를 확인하세요.");if(!new[]{"sequential","independent"}.Contains(p.Mode))throw new ArgumentException("실행 순서를 선택하세요.");foreach(var a in p.Actions)if(!sessionKinds.Contains(a.Kind))throw new ArgumentException("지원하지 않는 세션 동작: "+a.Kind);if(!String.IsNullOrEmpty(p.TerminalHost)&&!new[]{"windows-terminal","cmd"}.Contains(p.TerminalHost))throw new ArgumentException("세션 터미널 호스트를 확인하세요.");if(!String.IsNullOrEmpty(p.WorkspaceProfile)&&!Profiles().Any(x=>x.Id==p.WorkspaceProfile))throw new ArgumentException("작업공간 프로필을 확인하세요.");}
  public void SaveSession(DevelopmentSession p){ValidateSession(p);var store=Sessions();var current=store.Presets.FirstOrDefault(x=>x.Id==p.Id);p.Builtin=new[]{"ai-coding","opencode","web","review"}.Contains(p.Id);if(current==null)store.Presets.Add(p);else store.Presets[store.Presets.IndexOf(current)]=p;SaveLocal("development-sessions",store);}
  public void DeleteSession(string id){var store=Sessions();var preset=store.Presets.FirstOrDefault(x=>x.Id==id);if(preset==null)throw new ArgumentException("세션이 없습니다.");if(preset.Builtin)throw new ArgumentException("기본 세션은 삭제하지 않습니다. 동작을 편집하거나 복제하세요.");store.Presets.Remove(preset);SaveLocal("development-sessions",store);}
  public string SessionPreview(ProjectEntry p,DevelopmentSession preset,DeveloperPreferences preferences=null){ValidateDirectory(p.Directory);ValidateSession(preset);var prefs=preferences??Preferences(p);string profile=String.IsNullOrEmpty(preset.WorkspaceProfile)?prefs.WorkspaceProfile:preset.WorkspaceProfile;return preset.Name+"\n프로젝트: "+p.Name+"\n폴더: "+p.Directory+"\n배포판: "+(prefs.WslDistribution??"미지정")+"\n터미널: "+(String.IsNullOrEmpty(preset.TerminalHost)?prefs.TerminalHost:preset.TerminalHost)+"\n순서: "+(preset.Mode=="sequential"?"순차 요청":"독립 요청")+"\n\n"+String.Join("\n",preset.Actions.Where(a=>a.Enabled).Select((a,i)=>(i+1)+". "+(a.Kind=="ai"?"기본 AI CLI: "+prefs.DefaultAiCli:a.Kind=="project-terminal"?"프로젝트 터미널: "+prefs.TerminalHost:DeveloperText.Action(a.Kind))+(a.Kind=="command"?" · 사용자 명령 별도 동의 필요":"")))+(String.IsNullOrEmpty(profile)?"":"\n작업공간: "+profile+"\n"+ProfilePreview(Profiles().First(x=>x.Id==profile)))+"\n\n성공은 실행 요청·사전 경로 검사 기준입니다. CLI 대화·개발 서버 준비 완료를 의미하지 않습니다.";}
  public SessionRun[] SessionHistory(){var state=State("development-history");object value;return state.TryGetValue("Runs",out value)?Json.Deserialize<SessionRun[]>(Json.Serialize(value)):new SessionRun[0];}
  void SaveSessionRun(SessionRun run){using(var mutex=new Mutex(false,ScopedMutex("DevelopmentHistory"))){if(!mutex.WaitOne(5000))throw new IOException("개발 이력 저장이 사용 중입니다.");try{var list=SessionHistory().Where(x=>x.Id!=run.Id).ToList();list.Insert(0,run);GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","development-history.json"),Json.Serialize(new {Runs=list.Take(50).ToArray()}),false);}finally{mutex.ReleaseMutex();}}}
  public SessionRun StartSession(ProjectEntry p,DevelopmentSession preset,bool allowCommand=false,bool automation=false,DeveloperPreferences preferences=null){ValidateSession(preset);ValidateProject(p);if(automation&&!preset.AllowAutomation)throw new ArgumentException("이 세션은 자동 실행을 허용하지 않았습니다.");if(automation&&preset.Actions.Any(a=>a.Enabled&&a.Kind=="command"))throw new ArgumentException("자동화에서 프로젝트 명령은 실행하지 않습니다.");var prefs=Json.Deserialize<DeveloperPreferences>(Json.Serialize(preferences??Preferences(p)));if(!String.IsNullOrEmpty(preset.TerminalHost))prefs.TerminalHost=preset.TerminalHost;
   using(var mutex=new Mutex(false,ScopedMutex("DevelopmentSessionLaunch"))){if(!mutex.WaitOne(0))throw new InvalidOperationException("다른 개발 세션 실행을 시작하는 중입니다.");try{var last=State("development-last-start");DateTimeOffset time;if(DesktopService.S(last,"Project")==p.Id&&DesktopService.S(last,"Preset")==preset.Id&&DateTimeOffset.TryParse(DesktopService.S(last,"Time"),out time)&&DateTimeOffset.Now-time<TimeSpan.FromSeconds(5))throw new InvalidOperationException("같은 개발 세션의 연속 시작을 잠시 막았습니다.");GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","development-last-start.json"),Json.Serialize(new {Project=p.Id,Preset=preset.Id,Time=DateTimeOffset.Now.ToString("o")}),false);
    var run=new SessionRun{Id=Guid.NewGuid().ToString("N"),ProjectId=p.Id,PresetId=preset.Id,Started=DateTimeOffset.Now.ToString("o"),Active=true};SaveSessionRun(run);if(!automation)AutomationEvent("session-started",p.Id);
    string profile=String.IsNullOrEmpty(preset.WorkspaceProfile)?prefs.WorkspaceProfile:preset.WorkspaceProfile;if(!String.IsNullOrEmpty(profile)){try{Action("profile-apply",profile);run.Actions.Add(new LaunchResult{Action="profile",Status="확인",Detail="작업공간 적용 요청 완료"});}catch(Exception e){run.Actions.Add(new LaunchResult{Action="profile",Status="실패",Detail=e.Message});}}
    Func<SessionAction,LaunchResult> execute=a=>{try{if(a.Kind=="command"&&!allowCommand)return new LaunchResult{Action=a.Kind,Status="건너뜀",Detail="직접 명령 실행 동의 없음"};if(a.Kind=="repository"&&String.IsNullOrEmpty(p.RepositoryUrl))return new LaunchResult{Action=a.Kind,Status="건너뜀",Detail="저장소 URL 미지정"};return new LaunchResult{Action=a.Kind,Status="요청 전달",Detail=LaunchDeveloper(p,a.Kind=="tool"?"tool:"+a.Value:a.Kind,prefs)};}catch(Exception e){return new LaunchResult{Action=a.Kind,Status="실패",Detail=e.Message};}};
    var actions=preset.Actions.Where(x=>x.Enabled).ToArray();if(preset.Mode=="independent"){var tasks=actions.Select(a=>Task.Factory.StartNew(()=>execute(a))).ToArray();Task.WaitAll(tasks);run.Actions.AddRange(tasks.Select(t=>t.Result));}else foreach(var a in actions)run.Actions.Add(execute(a));run.Result=run.Actions.Any(x=>x.Status=="실패")?"일부 실패":run.Actions.Any(x=>x.Status=="건너뜀")?"일부 건너뜀":"실행 요청 전달";SaveSessionRun(run);RecordDeveloperUse(p,"session",prefs,preset.Id);GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","development-last-start.json"),Json.Serialize(new {Project=p.Id,Preset=preset.Id,Time=DateTimeOffset.Now.ToString("o")}),false);GuntConfiguration.Atomic(Root,Path.Combine(Root,"state","development-resume.json"),Json.Serialize(new {ProjectId=p.Id,Preset=preset,Preferences=prefs,RunId=run.Id}),false);return run;
   }finally{mutex.ReleaseMutex();}}}
  public string EndDevelopmentSession(){var run=SessionHistory().FirstOrDefault(x=>x.Active);if(run==null)return "진행 중으로 표시된 개발 세션이 없습니다.";run.Active=false;run.Ended=DateTimeOffset.Now.ToString("o");SaveSessionRun(run);AutomationEvent("session-ended",run.ProjectId);return "세션 종료를 기록했습니다. 편집기·터미널은 종료하지 않았습니다.";}
  public Tuple<ProjectEntry,DevelopmentSession,DeveloperPreferences> ResumeConfiguration(){var state=State("development-resume");if(state.Count==0)throw new ArgumentException("다시 시작할 개발 세션 기록이 없습니다.");var p=Projects().FirstOrDefault(x=>x.Id==S(state,"ProjectId"));if(p==null)throw new ArgumentException("기록된 프로젝트가 없습니다. 경로를 먼저 복구하세요.");ValidateDirectory(p.Directory);return Tuple.Create(p,Json.Deserialize<DevelopmentSession>(Json.Serialize(state["Preset"])),Json.Deserialize<DeveloperPreferences>(Json.Serialize(state["Preferences"])));}
 }
}
